function header(active = "/", language2 = "he") {
  const links = nav.map(([url, label2]) => `<a class="nav-link" href="${url}" ${active === url ? 'aria-current="page"' : ""}><span class="nav-link-text">${label2}</span></a>`).join("");
  const switchLabel = language2 === "he" ? "\u05D4\u05E6\u05D2\u05EA \u05D4\u05D0\u05EA\u05E8 \u05D1\u05D0\u05E0\u05D2\u05DC\u05D9\u05EA" : "\u05D4\u05E6\u05D2\u05EA \u05D4\u05D0\u05EA\u05E8 \u05D1\u05E2\u05D1\u05E8\u05D9\u05EA";
  return `<header class="site-header" data-header><div class="header-bar">${logo()}<nav class="site-nav" id="site-nav" aria-label="\u05E0\u05D9\u05D5\u05D5\u05D8 \u05E8\u05D0\u05E9\u05D9"><div class="site-nav-links">${links}</div><a class="nav-cta-mobile" href="/contact">\u05D3\u05D1\u05E8\u05D5 \u05D0\u05D9\u05EA\u05E0\u05D5 <span aria-hidden="true">\u2197</span></a></nav><div class="nav-actions"><button class="lang-toggle" type="button" aria-label="${switchLabel}">${language2 === "he" ? "EN" : "\u05E2\u05D1\u05E8\u05D9\u05EA"}</button><a class="pill pill-blue nav-cta" href="/contact" data-magnetic>\u05D1\u05D5\u05D0\u05D5 \u05E0\u05D3\u05D1\u05E8 <span aria-hidden="true">\u2197</span></a><button class="menu-toggle" type="button" aria-controls="site-nav" aria-expanded="false" aria-label="\u05E4\u05EA\u05D9\u05D7\u05EA \u05EA\u05E4\u05E8\u05D9\u05D8"><span></span><span></span></button></div></div></header>`;
}
function footer() {
  return `<footer class="site-footer" data-sky="night"><div class="wrap footer-cta"><p class="footer-kicker">\u05D4\u05E9\u05DC\u05D1 \u05D4\u05D1\u05D0</p><a class="footer-big" href="/contact" data-magnetic data-cursor="\u05DB\u05EA\u05D1\u05D5 \u05DC\u05E0\u05D5"><span class="footer-big-line" data-anim="lines">\u05D9\u05E9 \u05DC\u05DB\u05DD \u05DE\u05E9\u05D4\u05D5 \u05D1\u05E8\u05D0\u05E9?</span><span class="footer-big-line footer-big-accent" data-anim="lines">\u05E0\u05D3\u05D1\u05E8.</span></a></div><div class="wrap footer-grid"><div class="footer-brand">${logo()}<p>\u05D0\u05EA\u05E8\u05D9\u05DD, \u05DE\u05DE\u05E9\u05E7\u05D9\u05DD \u05D5\u05DE\u05E2\u05E8\u05DB\u05D5\u05EA \u05E9\u05E0\u05D1\u05E0\u05D9\u05DD \u05E1\u05D1\u05D9\u05D1 \u05DE\u05D4 \u05E9\u05D7\u05E9\u05D5\u05D1 \u05DC\u05E2\u05E1\u05E7 \u05E9\u05DC\u05DB\u05DD.</p></div><div class="footer-col"><span>\u05DC\u05D2\u05DC\u05D5\u05EA</span><a href="/services">\u05E9\u05D9\u05E8\u05D5\u05EA\u05D9\u05DD</a><a href="/projects">\u05E7\u05D5\u05E0\u05E1\u05E4\u05D8\u05D9\u05DD</a><a href="/process">\u05D0\u05D9\u05DA \u05E2\u05D5\u05D1\u05D3\u05D9\u05DD</a><a href="/about">\u05E2\u05DC\u05D9\u05E0\u05D5</a></div><div class="footer-col"><span>\u05DC\u05D4\u05EA\u05D7\u05D1\u05E8</span><a href="/contact">\u05D9\u05E6\u05D9\u05E8\u05EA \u05E7\u05E9\u05E8</a><a href="mailto:ripping_births9f@icloud.com" dir="ltr">ripping_births9f@icloud.com</a></div><div class="footer-col"><span>\u05DE\u05D9\u05D3\u05E2</span><a href="/privacy">\u05E4\u05E8\u05D8\u05D9\u05D5\u05EA</a><a href="/terms">\u05EA\u05E0\u05D0\u05D9 \u05E9\u05D9\u05DE\u05D5\u05E9</a><a href="/accessibility">\u05E0\u05D2\u05D9\u05E9\u05D5\u05EA</a></div></div><div class="wrap footer-bottom"><span dir="ltr">\xA9 2026 devSkyline</span><span>\u05D0\u05EA\u05E8\u05D9\u05DD \u05DC\u05E2\u05E1\u05E7\u05D9\u05DD</span></div></footer>`;
}
function accessibility(language2) {
  return accessibilityMarkup(language2);
}
function shell(content, active = "/", language2 = "he") {
  return `${header(active, language2)}<main id="main-content" tabindex="-1">${content}</main>${footer()}${accessibility(language2)}<div class="cursor-tag" aria-hidden="true"><span></span></div>`;
}
function pageHero({ label: label2, lines, description, sky = "deep", before = "" }) {
  return `<section class="page-hero" data-sky="${sky}"><div class="wrap page-hero-inner">${before}<p class="kicker" data-intro>${label2}</p><h1 class="page-title">${lines.map((line, index) => `<span class="title-line${index === lines.length - 1 && lines.length > 1 ? " title-line-soft" : ""}" data-intro-line>${line}</span>`).join("")}</h1><p class="page-lede" data-intro>${description}</p></div><div class="page-hero-glass" aria-hidden="true" data-speed="0.18"></div></section>`;
}

